arguments.code:
import json, collections, pathlib
rows=[json.loads(l) for l in open(pathlib.Path.home()/'.cache/oxide/agent-eval/results/run1.jsonl')]
print(collections.Counter(r['status'] for r in rows))
ox=[r for r in rows if r['arm']=='oxide' and r['resolved'] is not None]
for r in ox: print(r['task'], r['rep'], r['resolved'], {k:v for k,v in r['calls'].items()})
errs=[r for r in rows if r['resolved'] is None]; print([ (r['task'],r['arm'],r.get('error','')[:150]) for r in errs])
tot=collections.Counter(); 
for r in rows:
    if r['resolved'] is not None: tot.update({(r['arm'],k):v for k,v in r.get('calls',{}).items()})
print(sorted(tot.items(), key=lambda x:-x[1]))
done=collections.Counter((r['task'],r['arm']) for r in rows); print([k for k,v in done.items() if v<3])

