### Print the local server database path with opencode debug paths db

Source: https://github.com/anomalyco/opencode/blob/dev/services/site/src/docs/content/cli/providers.mdx

Prints the SQLite database path where saved API keys and OAuth tokens are stored. The usual release path is `~/.local/share/opencode/opencode.db`, which `XDG_DATA_HOME`, the release channel, and `OPENCODE_DB` can change.

```bash
opencode debug paths db
```

--------------------------------

### XDG_DATA_HOME Global Roots for App Data, Cache, Config, and State

Source: https://github.com/anomalyco/opencode/blob/dev/packages/util/src/global-roots.ts

The `global-roots.ts` utility reads `XDG_DATA_HOME` (falling back to `~/.local/share`), `XDG_CACHE_HOME` (`~/.cache`), `XDG_CONFIG_HOME` (`~/.config`), and `XDG_STATE_HOME` (`~/.local/state`) to compute the app-specific base directories. All global OpenCode paths (credentials DB auth.json legacy, config, cache, etc.) are rooted under these XDG directories.

```typescript
import os from "os"
import path from "path"

const home = os.homedir()
const data = process.env.XDG_DATA_HOME || (home ? path.join(home, ".local", "share") : undefined)
const cache = process.env.XDG_CACHE_HOME || (home ? path.join(home, ".cache") : undefined)
const config = process.env.XDG_CONFIG_HOME || (home ? path.join(home, ".config") : undefined)
const state = process.env.XDG_STATE_HOME || (home ? path.join(home, ".local", "state") : undefined)

/** The XDG base directories that root opencode's global paths. */
export function roots(app: string) {
  return {
    data: path.join(data!, app),
    cache: path.join(cache!, app),
    config: path.join(config!, app),
    state: path.join(state!, app),
    tmp: path.join(os.tmpdir(), app),
  }
}
```

--------------------------------

### XDG base directory resolution for OpenCode data/config/cache/state

Source: https://github.com/anomalyco/opencode/blob/dev/packages/util/src/global-roots.ts

Resolves the OpenCode data directory from XDG_DATA_HOME (falling back to ~/.local/share), then appends the application name ('opencode') to produce data, cache, config, and state paths. Setting XDG_DATA_HOME before startup redirects where the server stores its database, credentials, and configuration.

```typescript
import os from "os"
import path from "path"

const home = os.homedir()
const data = process.env.XDG_DATA_HOME || (home ? path.join(home, ".local", "share") : undefined)
const cache = process.env.XDG_CACHE_HOME || (home ? path.join(home, ".cache") : undefined)
const config = process.env.XDG_CONFIG_HOME || (home ? path.join(home, ".config") : undefined)
const state = process.env.XDG_STATE_HOME || (home ? path.join(home, ".local", "state") : undefined)

export function roots(app: string) {
  return {
    data: path.join(data!, app),
    cache: path.join(cache!, app),
    config: path.join(config!, app),
    state: path.join(state!, app),
    tmp: path.join(os.tmpdir(), app),
  }
}
```

--------------------------------

### Storage

Source: https://github.com/anomalyco/opencode/blob/dev/services/site/src/docs/content/cli/providers.mdx

The usual release path is `~/.local/share/opencode/opencode.db`; `XDG_DATA_HOME`, the release channel, and `OPENCODE_DB`
can change it. Do not edit the database to manage credentials; use `/connect` or the `auth` commands.

--------------------------------

### XDG_DATA_HOME, auth.json path, and log directory

Source: https://github.com/anomalyco/opencode/blob/dev/packages/util/src/global-roots.ts

`XDG_DATA_HOME` defaults to `~/.local/share` and roots opencode's global data directory. `auth.json` is read from `global.data/auth.json` during the legacy credential migration. The desktop log directory is under `userData/logs/<timestamp>/`, and server logs are stored at `$XDG_DATA_HOME/opencode/log/` (or `userData/opencode/log/`).

```typescript
// global-roots.ts – XDG_DATA_HOME default and global root derivation
const home = os.homedir()
const data = process.env.XDG_DATA_HOME || (home ? path.join(home, ".local", "share") : undefined)

export function roots(app: string) {
  return {
    data: path.join(data!, app),
    cache: path.join(cache!, app),
    config: path.join(config!, app),
    state: path.join(state!, app),
    tmp: path.join(os.tmpdir(), app),
  }
}

// migration – auth.json resides at global.data/auth.json
const global = yield* Global.Service
return yield* importLegacyCredentials(tx, path.join(global.data, "auth.json"))

// logging.ts – log directory and server log roots
root = path.join(app.getPath("userData"), "logs")
run = path.join(root, stamp())

// serverLogRoots – where server logs are stored
function serverLogRoots(path: Path.Path) {
  const xdgData = process.env.XDG_DATA_HOME || path.join(homedir(), ".local", "share")
  return [...new Set([path.join(xdgData, "opencode", "log"), path.join(app.getPath("userData"), "opencode", "log")])]
}
```

